/** Real registries, immutable archives and native chunk generation; excluded from the gameplay JAR. */
final class Cycle17Acceptance {
    private static final Identifier OVERWORLD=Identifier.withDefaultNamespace("overworld");
    private static final String PROFILE="/dimensions/minecraft:overworld/generator/";
    static void fresh(MinecraftServer server)throws Exception{
        var directory=ModpackRuntime.directory();
        corridor(server,directory);
        districts(server,directory);
        inheritance(server,directory);
        System.out.println("WA_CYCLE17_CORRIDORS_DISTRICTS_INHERITANCE_PASS");
    }
    private static JsonObject generator(JsonObject json){return json.getAsJsonObject("dimensions").getAsJsonObject("minecraft:overworld").getAsJsonObject("generator");}
    private static void corridor(MinecraftServer server,Path directory)throws Exception{
        var original=PresetStudio.load(directory,"polygon_regions","1.5.0");var json=original.preset();var profile=generator(json).getAsJsonObject("profile");var regions=profile.getAsJsonArray("terrain_regions");var zone=regions.get(1).getAsJsonObject();zone.addProperty("mask","corridor");zone.remove("vertices");zone.addProperty("min_x",-84);zone.addProperty("min_z",-52);zone.addProperty("max_x",84);zone.addProperty("max_z",52);
        var corridor=new JsonObject();corridor.addProperty("radius",20);var points=new JsonArray();for(int[] p:List.of(new int[]{-64,-32},new int[]{0,-32},new int[]{0,32},new int[]{64,32})){var point=new JsonObject();point.addProperty("x",p[0]);point.addProperty("z",p[1]);points.add(point);}corridor.add("points",points);zone.add("corridor",corridor);zone.addProperty("biome","minecraft:desert");profile.addProperty("generator_version",6);
        var resources=new TreeMap<>(original.templates());String markerPath="data/validation/worldgen/structure/regional_marker.json";var marker=JsonParser.parseString(new String(resources.get(markerPath),StandardCharsets.UTF_8)).getAsJsonObject();var biomes=new JsonArray();biomes.add("minecraft:plains");biomes.add("minecraft:desert");marker.add("biomes",biomes);resources.put(markerPath,marker.toString().getBytes(StandardCharsets.UTF_8));var draft=new PresetStudio.Draft(PresetStudio.defaults("corridor_regions","1.7.0",original.manifest().options()),json,resources);PresetStudio.save(directory,"corridor_regions",draft,server.registryAccess());
        System.out.println("WA17_BUNDLE corridor minecraft:overworld validation:regional_marker "+PresetStudio.export(directory,"corridor_regions","1.7.0",server.registryAccess()));
    }
    private static void districts(MinecraftServer server,Path directory)throws Exception{
        var original=PresetStudio.load(directory,"prepared_house","1.6.0");var json=original.preset();var gen=generator(json);var profile=gen.getAsJsonObject("profile");var region=new JsonObject();region.addProperty("name","district_land");region.addProperty("mask","rectangle");region.addProperty("min_x",256);region.addProperty("min_z",256);region.addProperty("max_x",8192);region.addProperty("max_z",8192);region.addProperty("transition",0);region.addProperty("elevation",64);region.addProperty("relief",0);var terrain=new JsonObject();terrain.addProperty("landform","plateaus");region.add("terrain",terrain);var regions=new JsonArray();regions.add(region);profile.add("terrain",terrain.deepCopy());profile.add("terrain_regions",regions);profile.addProperty("generator_version",3);
        var resources=new TreeMap<>(original.templates());var definition=resources.get("data/validation/worldgen/structure/prepared_house.json");var selections=new JsonArray();
        for(int i=0;i<3;i++){String name="district_"+i;resources.put("data/validation/worldgen/structure/"+name+".json",definition.clone());var rule=new JsonObject();rule.addProperty("structure","validation:"+name);rule.addProperty("spacing",8);rule.addProperty("separation",6);var member=new JsonObject();member.addProperty("group",i<2?"village":"outpost");member.addProperty("exclusion","settlements");member.addProperty("weight",i==0?3:1);member.addProperty("min_distance",8);member.addProperty("region","district_land");rule.add("district",member);selections.add(rule);}
        var content=gen.getAsJsonObject("dimension_profile").getAsJsonObject("content");content.addProperty("version",2);content.add("structures",selections);
        var draft=new PresetStudio.Draft(PresetStudio.defaults("districts","1.7.0",original.manifest().options()),json,resources);var checked=PresetStudio.validate(draft,server.registryAccess());
        // Detached planning must be independent of input ordering and worker scheduling.
        var inputs=new ArrayList<SiteInspector.Input>();for(int x=4;x<10;x++)for(int z=4;z<10;z++)for(int i=0;i<3;i++){var id=Identifier.parse("validation:district_"+i);var p=SiteInspector.placements(checked,OVERWORLD,id).getFirst().getPotentialStructureChunk(18,x*8,z*8);inputs.add(SiteInspector.prepare(checked,OVERWORLD,id,18,p.x(),p.z(),server.registryAccess(),server.getStructureTemplateManager()));}
        var sequential=inputs.stream().map(Cycle17Acceptance::decision).toList();var parallel=inputs.parallelStream().map(Cycle17Acceptance::decision).toList();require(sequential.equals(parallel),"District planning changed on worker threads");require(sequential.contains("eligible")&&sequential.contains("rejected"),"District fixture did not exercise selection and exclusion");
        var reversed=json.deepCopy();var rules=generator(reversed).getAsJsonObject("dimension_profile").getAsJsonObject("content").getAsJsonArray("structures");var reverse=new JsonArray();for(int i=rules.size()-1;i>=0;i--)reverse.add(rules.get(i));generator(reversed).getAsJsonObject("dimension_profile").getAsJsonObject("content").add("structures",reverse);var reverseChecked=PresetStudio.validate(new PresetStudio.Draft(draft.manifest(),reversed,resources),server.registryAccess());for(int i=0;i<inputs.size();i++){var input=inputs.get(i);require(sequential.get(i).equals(decision(SiteInspector.prepare(reverseChecked,OVERWORLD,input.structure().unwrapKey().orElseThrow().identifier(),18,input.chunk().x(),input.chunk().z(),server.registryAccess(),server.getStructureTemplateManager()))),"District list order changed a placement");}
        var first=inputs.getFirst();var search=SiteSearch.search(first,SiteInspector.placements(checked,OVERWORLD,first.structure().unwrapKey().orElseThrow().identifier()),new SiteSearch.Bounds(32,32,80,80,128,8),true);require(!search.getListOrEmpty("results").isEmpty(),"District search found no accepted sites");for(var value:search.getListOrEmpty("results")){var row=(CompoundTag)value;require(decision(SiteInspector.prepare(checked,OVERWORLD,first.structure().unwrapKey().orElseThrow().identifier(),18,row.getIntOr("chunk_x",0),row.getIntOr("chunk_z",0),server.registryAccess(),server.getStructureTemplateManager())).equals("eligible"),"District search disagreed with inspection");}
        PresetStudio.save(directory,"districts",draft,server.registryAccess());System.out.println("WA17_BUNDLE district minecraft:overworld validation:district_0 "+PresetStudio.export(directory,"districts","1.7.0",server.registryAccess()));
    }
    private static void inheritance(MinecraftServer server,Path directory)throws Exception{
        var original=PresetStudio.load(directory,"prepared_house","1.6.0");var m=original.manifest();var policy=new BundleManifest(m.preset(),"Reusable house base","Pinned validation base","Validation","1.7.0",BundleManifest.Lock.PARTIAL,m.options(),List.of(),Map.of(OVERWORLD,List.of(BundleManifest.Feature.STRUCTURES)),List.of(),m.requiredMods(),false);
        var parent=original.withManifest(policy);var archive=PresetStudio.save(directory,"reusable_base",parent,server.registryAccess());var bytes=Files.readAllBytes(archive);var hash=PresetStudio.fingerprint(directory,"reusable_base","1.7.0");
        denied(()->PresetStudio.derive(directory,"reusable_base","1.7.0","0".repeat(64),"wrong_pin","1.7.0",server.registryAccess()));denied(()->PresetStudio.derive(directory,"absent","1.7.0",hash,"missing","1.7.0",server.registryAccess()));
        var child=PresetStudio.derive(directory,"reusable_base","1.7.0",hash,"inherited_partial","1.7.0",server.registryAccess());child=PresetStudio.override(child,PROFILE+"dimension_profile/content/structures/0/spacing",new JsonPrimitive(20),false,server.registryAccess());var frozen=child;
        denied(()->PresetStudio.override(frozen,PROFILE+"profile/material",new JsonPrimitive("minecraft:gold_block"),false,server.registryAccess()));
        var unlocked=PresetStudio.defaults("bad_child","1.7.0",m.options());denied(()->PresetStudio.validate(frozen.withManifest(unlocked),server.registryAccess()));
        var changed=new TreeMap<>(child.templates());String resource="data/validation/worldgen/structure/prepared_house.json";changed.put(resource,(new String(changed.get(resource),StandardCharsets.UTF_8)+" ").getBytes(StandardCharsets.UTF_8));denied(()->PresetStudio.validate(new PresetStudio.Draft(frozen.manifest(),frozen.preset(),changed),server.registryAccess()));
        PresetStudio.save(directory,"inherited_partial",child,server.registryAccess());var cm=child.manifest();var full=PresetStudio.duplicate(child,"inherited_full","1.7.0");var fm=full.manifest();full=full.withManifest(new BundleManifest(fm.preset(),fm.title(),fm.description(),fm.author(),fm.release(),BundleManifest.Lock.FULL,fm.options(),List.of(),Map.of(),List.of(),fm.requiredMods(),false,fm.inheritance()));PresetStudio.save(directory,"inherited_full",full,server.registryAccess());
        // Exported children contain everything they need; deleted or replaced parents cannot change them.
        try{Files.delete(archive);PresetStudio.validate(PresetStudio.load(directory,"inherited_partial","1.7.0"),server.registryAccess());PresetStudio.validate(PresetStudio.load(directory,"inherited_full","1.7.0"),server.registryAccess());Files.write(archive,new byte[]{42},StandardOpenOption.CREATE_NEW);PresetStudio.validate(PresetStudio.load(directory,"inherited_full","1.7.0"),server.registryAccess());denied(()->PresetStudio.derive(directory,"reusable_base","1.7.0",hash,"changed_parent","1.7.0",server.registryAccess()));}finally{Files.write(archive,bytes);}
        require(Arrays.equals(bytes,Files.readAllBytes(archive)),"Parent revision changed during child authoring");
        for(String name:List.of("reusable_base","inherited_partial","inherited_full"))System.out.println("WA17_INHERITED_BUNDLE "+name+" "+PresetStudio.export(directory,name,"1.7.0",server.registryAccess()));
        Cycle17AuthoringAcceptance.check(server);
        System.out.println("WA17_PINNED_SELF_CONTAINED_INHERITED_LOCKS_PASS");
    }
    static void generated(MinecraftServer server,String kind,Identifier id,Identifier dimension,int stage)throws Exception{
        if(kind.equals("corridor")){corridorGenerated(server,stage);return;}
        var level=server.getLevel(ResourceKey.create(Registries.DIMENSION,dimension));require(level!=null,"Missing district dimension");var gen=(SolidColumnGenerator)level.getChunkSource().getGenerator();var draft=PresetStudio.capture(PresetStudio.defaults("district_inspection","1.7.0",server.getWorldGenSettings().options()),server.getWorldGenSettings().dimensions(),server.registryAccess());var checked=PresetStudio.validate(draft,server.registryAccess());
        var positions=new ArrayList<ChunkPos>();for(int x=4;x<9;x++)for(int z=4;z<9;z++)for(var rule:gen.structureRules()){var p=StructureDistricts.placement(rule).getPotentialStructureChunk(18,x*8,z*8);if(!positions.contains(p))positions.add(p);}if(stage==2)Collections.reverse(positions);
        var signatures=new TreeMap<String,String>();var sites=new ArrayList<ChunkPos>();int rejected=0,markers=0;for(var p:positions){var expected=new HashMap<String,Boolean>();for(var rule:gen.structureRules()){var selected=rule.structure().unwrapKey().orElseThrow().identifier();expected.put(selected.toString(),decision(SiteInspector.prepare(checked,dimension,selected,18,p.x(),p.z(),server.registryAccess(),server.getStructureTemplateManager())).equals("eligible"));}var chunk=level.getChunk(p.x(),p.z());int atSite=0;for(var rule:gen.structureRules()){String selected=rule.structure().unwrapKey().orElseThrow().identifier().toString();var start=chunk.getStartForStructure(rule.structure().value());boolean valid=start!=null&&start.isValid();require(valid==expected.get(selected),"Inspector and native district generation disagree at "+p+" for "+selected);if(!valid){rejected++;continue;}atSite++;sites.add(p);var signature=new StringBuilder();var box=start.getBoundingBox();for(int x=box.minX()>>4;x<=box.maxX()>>4;x++)for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)level.getChunk(x,z);for(var piece:start.getPieces()){var origin=(BlockPos)AssemblyAcceptance.call(piece,"origin");var entry=AssemblyAcceptance.call(piece,"entry");var template=(NativeTemplate)AssemblyAcceptance.call(entry,"template");for(var cell:template.blocks()){var pos=origin.offset(cell.pos());require(StructureDistricts.cellAllowed(gen,rule.structure().value(),pos.getX(),pos.getZ()),"District cell escaped its named region");require(level.getBlockState(pos)==cell.state(),"District state changed at "+pos);}for(var marker:((Map<?,?>)AssemblyAcceptance.call(entry,"markers")).values()){var pos=origin.offset((BlockPos)AssemblyAcceptance.call(marker,"pos"));require(level.getBlockState(pos).isAir()&&level.getBlockState(pos.above()).isAir()&&!level.getBlockState(pos.below()).isAir(),"District marker unsafe");markers++;}signature.append(origin).append(AssemblyAcceptance.call(entry,"toTag"));}signatures.put(p+"/"+selected,PresetInheritance.fingerprint(signature.toString().getBytes(StandardCharsets.UTF_8)));}require(atSite<=1,"Districts overlapped a shared grid site");}
        require(sites.size()>=5&&rejected>0&&markers==sites.size(),"District fixture did not generate enough marked sites");for(int i=0;i<sites.size();i++)for(int j=i+1;j<sites.size();j++){long dx=sites.get(i).x()-sites.get(j).x(),dz=sites.get(i).z()-sites.get(j).z();require(dx*dx+dz*dz>=64,"District minimum separation failed");}
        var path=server.getWorldPath(LevelResource.DATA).resolve("worldarchitect-district17.json");String result=new Gson().toJson(signatures);if(stage==1)Files.writeString(path,result,StandardOpenOption.CREATE_NEW);else require(Files.readString(path).equals(result),"District starts changed after restart and reverse requests");System.out.println("WA17_GENERATION_PASS kind=district stage="+stage+" sites="+sites.size()+" markers="+markers);
    }
    private static void corridorGenerated(MinecraftServer server,int stage)throws Exception{
        var level=server.overworld();var gen=(SolidColumnGenerator)level.getChunkSource().getGenerator();require(gen.terrainRegions().orElseThrow().version()==6,"Corridor profile lost version 6");var digest=java.security.MessageDigest.getInstance("SHA-256");int inside=0,outside=0;for(int cx=-6;cx<=6;cx++)for(int cz=-5;cz<=5;cz++){var chunk=level.getChunk(cx,cz);for(int x=cx*16;x<cx*16+16;x++)for(int z=cz*16;z<cz*16+16;z++){double horizontalA=Math.hypot(x-Math.clamp(x,-64,0),z+32),vertical=Math.hypot(x,z-Math.clamp(z,-32,32)),horizontalB=Math.hypot(x-Math.clamp(x,0,64),z-32);boolean expected=Math.min(vertical,Math.min(horizontalA,horizontalB))<=20;var p=new BlockPos(x,64,z);require(chunk.getBlockState(p).is(Blocks.DIAMOND_BLOCK)==expected,"Corridor material rule escaped independent capsule mask at "+p);if(expected)inside++;else outside++;if(x%4==0&&z%4==0){boolean desert=chunk.getNoiseBiome(x>>2,16,z>>2).is(net.minecraft.world.level.biome.Biomes.DESERT);require(desert==expected,"Corridor biome disagreed with the shared mask at "+p);digest.update((byte)(desert?1:0));}for(int y=20;y<=65;y++){var state=chunk.getBlockState(new BlockPos(x,y,z));if(state.is(Blocks.GOLD_ORE)||state.is(Blocks.AMETHYST_BLOCK))require(!expected,"Corridor winner leaked ore or decoration");digest.update(state.toString().getBytes(StandardCharsets.UTF_8));}}}
        require(inside>0&&outside>0,"Corridor fixture missed either side");String hash=HexFormat.of().formatHex(digest.digest());var path=server.getWorldPath(LevelResource.DATA).resolve("worldarchitect-corridor17.txt");if(stage==1)Files.writeString(path,hash,StandardOpenOption.CREATE_NEW);else require(Files.readString(path).equals(hash),"Corridor chunks changed after restart");System.out.println("WA17_GENERATION_PASS kind=corridor stage="+stage+" inside="+inside+" outside="+outside);
    }
    private static String decision(SiteInspector.Input input){for(int i=0;i<4;i++){String result=SiteInspector.inspect(input).getStringOr("status","");if(!result.equals("incomplete"))return result;}throw new AssertionError("Small district probe did not complete");}
    @FunctionalInterface private interface Op{void run()throws Exception;}
    private static void denied(Op op)throws Exception{try{op.run();throw new AssertionError("Expected inherited-preset rejection");}catch(IOException|IllegalArgumentException expected){}}
    private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
}
